#import "TFAIModels.h"
#import "TFAIUIHelpers.h"
NSString *TFAIModelKey(NSDictionary *c){return [NSString stringWithFormat:@"%@/%@",c[@"id"]?:@"",c[@"model"]?:@""];}
NSArray<NSDictionary *> *TFAIAvailableModels(void){NSMutableArray *result=[NSMutableArray new];for(NSDictionary *c in TFAIConnections.all){NSMutableOrderedSet *names=[NSMutableOrderedSet new];if([c[@"model"] length])[names addObject:c[@"model"]];for(id m in c[@"models"])if([m isKindOfClass:NSString.class]&&[m length])[names addObject:m];for(NSString *m in names){NSMutableDictionary *item=[c mutableCopy];item[@"model"]=m;if(![m isEqual:c[@"model"]])[item removeObjectForKey:@"capabilities"];[result addObject:item];}}return result;}
@interface TFAIModels : UITableViewController <UISearchResultsUpdating>
@property NSDictionary *current;
@property(copy) void (^selection)(NSDictionary *);
@property NSArray *groups;
@property NSArray *titles;
@property NSString *query;
@end
@implementation TFAIModels
- (void)viewDidLoad{[super viewDidLoad];self.title=@"选择模型";UISearchController *search=[[UISearchController alloc]initWithSearchResultsController:nil];search.searchResultsUpdater=self;search.obscuresBackgroundDuringPresentation=NO;search.searchBar.placeholder=@"模型名称或服务商";self.navigationItem.searchController=search;self.navigationItem.hidesSearchBarWhenScrolling=NO;self.navigationItem.leftBarButtonItem=AIBar(@"xmark",@"关闭",self,@selector(close));self.navigationItem.rightBarButtonItem=AIBar(@"slider.horizontal.3",@"管理连接",self,@selector(settings));UILabel *hint=[UILabel new];hint.text=@"  只影响下一次请求 · 长按模型可加入常用";hint.font=[UIFont preferredFontForTextStyle:UIFontTextStyleCaption1];hint.textColor=UIColor.secondaryLabelColor;hint.numberOfLines=0;hint.frame=CGRectMake(0,0,320,44);self.tableView.tableHeaderView=hint;[self reload];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];[self reload];}
- (void)reload{NSArray *all=TFAIAvailableModels();NSString *query=self.query?:@"";NSArray *filtered=[all filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *c,NSDictionary *bindings){return !query.length||[c[@"model"] localizedCaseInsensitiveContainsString:query]||[c[@"name"] localizedCaseInsensitiveContainsString:query];}]];NSMutableArray *groups=[NSMutableArray new],*titles=[NSMutableArray new];for(NSArray *spec in @[@[@"TFAI.FavoriteModels",@"常用"],@[@"TFAI.RecentModels",@"最近"]]){NSArray *keys=[NSUserDefaults.standardUserDefaults arrayForKey:spec[0]]?:@[];NSMutableArray *rows=[NSMutableArray new];for(NSString *key in keys)for(NSDictionary *c in filtered)if([TFAIModelKey(c) isEqual:key])[rows addObject:c];if(rows.count){[titles addObject:spec[1]];[groups addObject:rows];}}for(NSDictionary *connection in TFAIConnections.all){NSArray *rows=[filtered filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *c,NSDictionary *bindings){return [c[@"id"] isEqual:connection[@"id"]];}]];if(rows.count){[titles addObject:connection[@"name"]?:@"服务商"];[groups addObject:rows];}}self.groups=groups;self.titles=titles;[self.tableView reloadData];if(!groups.count){UILabel *empty=[UILabel new];empty.numberOfLines=0;empty.textAlignment=NSTextAlignmentCenter;empty.text=@"暂无匹配模型\n点击右上角管理连接\n可手动填写模型 ID 或获取列表";empty.font=[UIFont preferredFontForTextStyle:UIFontTextStyleBody];empty.textColor=UIColor.secondaryLabelColor;self.tableView.backgroundView=empty;}else self.tableView.backgroundView=nil;}
- (void)updateSearchResultsForSearchController:(UISearchController *)s{self.query=s.searchBar.text;[self reload];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return self.groups.count;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return [self.groups[s] count];}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return self.titles[s];}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSDictionary *c=self.groups[i.section][i.row];NSMutableArray *caps=[NSMutableArray new];for(NSString *key in @[@"text",@"stream",@"image",@"tools"]){NSString *status=c[@"capabilities"][key];if([status isEqual:@"supported"])[caps addObject:@{@"text":@"文本",@"stream":@"流式",@"image":@"图片",@"tools":@"工具"}[key]];}UITableViewCell *cell=AICell(c[@"model"],[NSString stringWithFormat:@"%@ · %@",c[@"name"],caps.count?[caps componentsJoinedByString:@" / "]:@"能力尚未验证"],@"cpu");cell.accessoryType=[TFAIModelKey(c) isEqual:TFAIModelKey(self.current)]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;return cell;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{NSDictionary *c=self.groups[i.section][i.row];NSMutableArray *recent=[[NSUserDefaults.standardUserDefaults arrayForKey:@"TFAI.RecentModels"] mutableCopy]?:[NSMutableArray new];[recent removeObject:TFAIModelKey(c)];[recent insertObject:TFAIModelKey(c) atIndex:0];if(recent.count>8)[recent removeLastObject];[NSUserDefaults.standardUserDefaults setObject:recent forKey:@"TFAI.RecentModels"];void(^selection)(NSDictionary *)=self.selection;[self dismissViewControllerAnimated:YES completion:^{if(selection)selection(c);}];}
- (UIContextMenuConfiguration *)tableView:(UITableView *)t contextMenuConfigurationForRowAtIndexPath:(NSIndexPath *)i point:(CGPoint)p{NSDictionary *c=self.groups[i.section][i.row];NSString *key=TFAIModelKey(c);BOOL favorite=[[NSUserDefaults.standardUserDefaults arrayForKey:@"TFAI.FavoriteModels"] containsObject:key];return [UIContextMenuConfiguration configurationWithIdentifier:nil previewProvider:nil actionProvider:^UIMenu *(NSArray *suggested){return [UIMenu menuWithChildren:@[[UIAction actionWithTitle:favorite?@"移出常用":@"加入常用" image:[UIImage systemImageNamed:favorite?@"star.slash":@"star"] identifier:nil handler:^(UIAction *a){NSMutableArray *keys=[[NSUserDefaults.standardUserDefaults arrayForKey:@"TFAI.FavoriteModels"] mutableCopy]?:[NSMutableArray new];if(favorite)[keys removeObject:key];else[keys addObject:key];[NSUserDefaults.standardUserDefaults setObject:keys forKey:@"TFAI.FavoriteModels"];[self reload];}]]];}];}
- (void)settings{[self.navigationController pushViewController:TFAISettingsController(nil) animated:YES];}
- (void)close{[self dismissViewControllerAnimated:YES completion:nil];}
@end
UIViewController *TFAIModelPicker(NSDictionary *selected,void(^selection)(NSDictionary *)){TFAIModels *v=[[TFAIModels alloc]initWithStyle:UITableViewStyleInsetGrouped];v.current=selected;v.selection=selection;return v;}
